// Shule AI v120 final report card design: one-page A4, child photo, watermark, uploaded signatures, no parent/guardian signature.
(function(){
  'use strict';
  if (window.__v120ReportCardFinalDesignLoaded) return;
  window.__v120ReportCardFinalDesignLoaded = true;

  const SHULE_DEFAULT = {
    schoolName: 'Shule AI',
    name: 'Shule AI',
    logo: 'assets/logo.png',
    primaryColor: '#083A85',
    accentColor: '#11B5B1',
    reportFooter: 'Generated by Shule AI.'
  };

  function esc(v){
    if (typeof escapeHtml === 'function') return escapeHtml(v);
    const d = document.createElement('div'); d.textContent = String(v ?? ''); return d.innerHTML;
  }
  function currentRole(){
    try { return String((typeof getCurrentRole === 'function' ? getCurrentRole() : localStorage.getItem('userRole') || localStorage.getItem('role') || '') || '').toLowerCase().replace('-', '_'); }
    catch { return ''; }
  }
  function hasFeature(feature){
    if (!feature) return true;
    if (currentRole() === 'super_admin' || currentRole() === 'superadmin') return true;
    if (typeof window.v118HasFeature === 'function') return window.v118HasFeature(feature);
    const st = window.ShulePlanState || {};
    const list = Array.isArray(st.features) ? st.features : [];
    if (list.length) return list.includes(feature);
    const plan = String(st.planCode || st.currentPlan || st.schoolTier || 'starter').toLowerCase();
    if (feature === 'school_branding') return plan.includes('growth') || plan.includes('enterprise');
    return true;
  }
  function mediaUrl(value){
    const raw = String(value || '').trim();
    if (!raw || raw === 'undefined' || raw === 'null' || raw === '/undefined' || raw === '/null') return '';
    if (/^(data:|blob:|https?:\/\/)/i.test(raw)) return raw;
    if (raw.startsWith('/uploads/')) {
      const base = String(window.API_BASE_URL || window.API_URL || '').replace(/\/$/, '');
      return base ? `${base}${raw}` : raw;
    }
    if (raw.startsWith('uploads/')) {
      const base = String(window.API_BASE_URL || window.API_URL || '').replace(/\/$/, '');
      return base ? `${base}/${raw}` : `/${raw}`;
    }
    try { return new URL(raw.replace(/^\/+/, ''), window.location.href).href; } catch { return raw; }
  }
  function initials(name){
    const text = String(name || 'Student').trim();
    if (typeof getInitials === 'function') return getInitials(text);
    return text.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase() || 'S';
  }
  function getBranding(school){
    const stored = (() => { try { return window.BrandingManager?.getStoredBranding ? window.BrandingManager.getStoredBranding() : JSON.parse(localStorage.getItem('schoolBranding') || '{}'); } catch { return {}; } })() || {};
    const raw = hasFeature('school_branding') ? { ...(school?.branding || {}), ...stored } : SHULE_DEFAULT;
    return {
      ...SHULE_DEFAULT,
      ...raw,
      schoolName: raw.schoolName || raw.displayName || raw.name || school?.schoolName || school?.name || SHULE_DEFAULT.schoolName,
      logo: raw.logoDataUrl || raw.logoUrl || raw.logo || school?.logo || school?.branding?.logoDataUrl || school?.branding?.logoUrl || school?.branding?.logo || SHULE_DEFAULT.logo,
      primaryColor: raw.primaryColor || SHULE_DEFAULT.primaryColor,
      accentColor: raw.accentColor || SHULE_DEFAULT.accentColor,
      reportFooter: raw.reportFooter || school?.reportFooter || SHULE_DEFAULT.reportFooter
    };
  }
  function componentLabels(subjects){
    const seen = new Map();
    (subjects || []).forEach(s => (s.components || []).forEach(c => {
      const label = c.label || c.assessmentName || c.assessment || c.type;
      if (!label) return;
      const key = String(label).toLowerCase();
      if (!seen.has(key)) seen.set(key, { label, order: Number(c.displayOrder || 99) });
    }));
    return [...seen.values()].sort((a,b)=>a.order-b.order).map(x=>x.label).slice(0,6);
  }
  function componentScore(subject, label){
    const row = (subject.components || []).find(c => String(c.label || c.assessmentName || c.assessment || c.type).toLowerCase() === String(label).toLowerCase());
    if (!row) return '-';
    if (row.score === undefined || row.score === null || row.score === '') return '-';
    return `${Number(row.score).toString()}${String(row.score).includes('%') ? '' : ''}`;
  }
  function signatureHtml(label, value){
    const src = mediaUrl(value);
    if (src) {
      return `<div class="sig-slot"><div class="sig-box"><img class="sig-img" src="${esc(src)}" alt="${esc(label)} signature" onerror="this.style.display='none';this.parentElement.classList.add('sig-missing')"></div><div class="sig-label">${esc(label)}</div></div>`;
    }
    return `<div class="sig-slot"><div class="sig-line"></div><div class="sig-label">${esc(label)}</div></div>`;
  }
  function safeComment(v, fallback=''){
    const text = String(v || fallback || '').trim();
    return esc(text || '');
  }
  function normalizeSubjects(data){
    const subjects = data?.academicSummary?.subjects || data?.subjects || [];
    return Array.isArray(subjects) ? subjects : [];
  }
  function buildRows(subjects, labels){
    const colCount = 1 + labels.length + 3;
    if (!subjects.length) return `<tr><td colspan="${colCount}">No published marks yet.</td></tr>`;
    return subjects.map(s => {
      const finalScore = s.average ?? s.score ?? s.final ?? '-';
      const grade = s.grade || s.level || s.competencyLevel || '-';
      const comment = s.comment || s.remarks || s.teacherComment || '';
      return `<tr><td class="subject-cell">${esc(s.subject || s.learningArea || 'Subject')}</td>${labels.map(l=>`<td>${esc(componentScore(s,l))}</td>`).join('')}<td><b>${esc(finalScore)}${typeof finalScore === 'number' ? '%' : ''}</b></td><td><b>${esc(grade)}</b></td><td class="comment-cell">${esc(comment)}</td></tr>`;
    }).join('');
  }

  window.buildReportCardHTML = async function(studentId){
    if (!studentId) {
      const dash = await (window.api?.student?.getDashboard ? api.student.getDashboard().catch(()=>null) : Promise.resolve(null));
      studentId = dash?.data?.student?.id || window.dashboardData?.student?.id || window.dashboardData?.selectedChildId || localStorage.getItem('shule_selected_child_id');
    }
    if (!studentId) throw new Error('Student ID not available');
    const res = await (typeof window.v113LoadReportCardDetails === 'function' ? window.v113LoadReportCardDetails(studentId) : window.api.students.getFullDetails(studentId));
    if (!res?.success) throw new Error(res?.message || 'Failed to load report card data');

    const data = res.data || {};
    const student = data.student || {};
    const user = data.user || {};
    const school = data.school || (typeof getCurrentSchool === 'function' ? getCurrentSchool() : {}) || {};
    const attendance = data.attendanceSummary || {};
    const academic = data.academicSummary || {};
    const branding = getBranding(school);
    const primary = branding.primaryColor || '#083A85';
    const accent = branding.accentColor || '#11B5B1';
    const logo = mediaUrl(branding.logo || branding.logoUrl || branding.logoDataUrl);
    const photo = mediaUrl(student.photo || student.profileImage || student.passportPhoto || user.profileImage);
    const subjects = normalizeSubjects(data);
    const labels = componentLabels(subjects);
    const studentName = user.name || student.name || 'Student';
    const className = student.className || student.grade || data.className || '-';
    const admNo = student.admissionNumber || student.admNo || student.elimuid || student.assessmentNumber || '-';
    const curriculum = (school.curriculum || school.system || student.curriculum || 'CBC').toString().toUpperCase();
    const dateText = new Date().toLocaleDateString();
    const sigs = data.reportSignatures || {};
    const classTeacherSig = sigs.classTeacher || data.classTeacher?.signatureUrl || data.classTeacher?.signature;
    const headteacherSig = sigs.headteacher || sigs.principal || data.headteacher?.signatureUrl || data.headteacher?.signature || data.principal?.signatureUrl || data.principal?.signature;
    const avg = academic.overallAverage ?? academic.average ?? 0;
    const rate = attendance.rate ?? 0;
    const present = attendance.present ?? '-';
    const absent = attendance.absent ?? '-';
    const late = attendance.late ?? 0;
    const feeBalance = data.feeBalance ?? data.outstandingFee ?? student.feeBalance ?? null;
    const ranking = data.ranking || data.positionSummary || {};
    const showClassPosition = ranking.showClassPosition === true || data.showClassPosition === true;
    const showStreamPosition = ranking.showStreamPosition === true || data.showStreamPosition === true;
    const classPositionText = ranking.classPosition ? `${ranking.classPosition}${ranking.classSize ? ' / ' + ranking.classSize : ''}` : '-';
    const streamPositionText = ranking.streamPosition ? `${ranking.streamPosition}${ranking.streamSize ? ' / ' + ranking.streamSize : ''}` : '-';
    const classTeacherComment = data.classTeacherComment || data.classTeacher?.comment || '';
    const headteacherComment = data.headteacherComment || data.principalComment || data.headteacher?.comment || data.principal?.comment || '';

    return `<!doctype html><html><head><meta charset="utf-8"><title>Report Card - ${esc(studentName)}</title><style>
      @page{size:A4;margin:7mm}*{box-sizing:border-box}body{margin:0;background:#fff;color:#172033;font-family:Arial,Helvetica,sans-serif;font-size:10.5px}.actions{display:flex;justify-content:flex-end;gap:8px;padding:8px}.actions button{border:1px solid #cbd5e1;border-radius:8px;background:#fff;padding:8px 12px;font-weight:700;cursor:pointer}.actions .primary{background:${primary};border-color:${primary};color:#fff}.report{width:100%;max-width:780px;min-height:1080px;margin:0 auto;border:1px solid #d9e2ef;border-radius:14px;padding:12px;position:relative;overflow:hidden}.wm{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:400px;height:400px;display:flex;align-items:center;justify-content:center;opacity:.055;z-index:0;pointer-events:none}.wm img{max-width:100%;max-height:100%;object-fit:contain}.top,.bio,.summary,.results,.comments,.signatures,.footer{position:relative;z-index:1}.top{display:grid;grid-template-columns:86px 1fr 80px;gap:10px;align-items:center;border-bottom:3px solid ${primary};padding-bottom:7px}.logo{width:82px;height:70px;object-fit:contain}.photo{width:74px;height:74px;border-radius:12px;object-fit:cover;border:2px solid ${accent}}.photo-placeholder{width:74px;height:74px;border-radius:12px;background:${primary};color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:20px}h1{margin:0;color:${primary};font-size:21px;line-height:1.1}.subtitle{font-weight:700;margin-top:3px}.muted{color:#64748b}.bio{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:8px 0}.box{border:1px solid #e2e8f0;border-radius:8px;padding:5px;background:#f8fafc;min-height:34px}.box b{display:block;color:${primary};font-size:9.5px;text-transform:uppercase;letter-spacing:.02em}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:8px 0}.results{width:100%;border-collapse:collapse;margin-top:6px}.results th{background:${primary};color:#fff;padding:5px;text-align:left;font-size:9.5px}.results td{border-bottom:1px solid #e2e8f0;padding:4px;vertical-align:top}.subject-cell{font-weight:700}.comment-cell{max-width:150px;font-size:9.5px}.comments{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:8px}.comment-box{min-height:48px}.signatures{display:grid;grid-template-columns:1fr 1fr 92px;gap:10px;align-items:end;margin-top:10px}.sig-box{height:40px;border-bottom:1px solid #334155;display:flex;align-items:flex-end;justify-content:center}.sig-img{max-height:38px;max-width:170px;object-fit:contain}.sig-line{height:40px;border-bottom:1px solid #334155}.sig-label{text-align:center;font-size:9.5px;margin-top:3px;color:#334155}.stamp{height:58px;border:1px dashed #94a3b8;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#64748b;font-size:9px}.footer{text-align:center;margin-top:6px;color:#64748b;font-size:9px}.no-parent-signature{display:none!important}@media print{body{font-size:9.5px}.actions{display:none}.report{border:0;border-radius:0;min-height:auto;padding:0}.box{padding:4px}.results th,.results td{padding:3px}.comments{margin-top:6px}.signatures{margin-top:8px}}
    </style></head><body><div class="actions"><button class="primary" onclick="window.print()">Print / Save PDF</button></div><main class="report">
      ${logo ? `<div class="wm"><img src="${esc(logo)}" alt="watermark"></div>` : ''}
      <section class="top">
        ${logo ? `<img class="logo" src="${esc(logo)}" alt="School logo">` : '<div></div>'}
        <div><h1>${esc(branding.schoolName || school.name || 'Shule AI School')}</h1><div class="subtitle">Official Student Report Card</div><div class="muted">${esc(curriculum)} • Generated ${esc(dateText)}</div></div>
        ${photo ? `<img class="photo" src="${esc(photo)}" alt="Student photo" onerror="this.replaceWith(Object.assign(document.createElement('div'),{className:'photo-placeholder',textContent:'${esc(initials(studentName))}'}))">` : `<div class="photo-placeholder">${esc(initials(studentName))}</div>`}
      </section>
      <section class="bio"><div class="box"><b>Student</b>${esc(studentName)}</div><div class="box"><b>Class / Grade</b>${esc(className)}</div><div class="box"><b>Adm / Assessment No.</b>${esc(admNo)}</div><div class="box"><b>Class Teacher</b>${esc(data.classTeacher?.name || 'Not assigned')}</div></section>
      <section class="summary"><div class="box"><b>Average</b>${esc(avg)}%</div><div class="box"><b>Attendance</b>${esc(rate)}%</div><div class="box"><b>Present</b>${esc(present)}</div><div class="box"><b>Absent / Late</b>${esc(absent)} / ${esc(late)}</div></section>
      <table class="results"><thead><tr><th>Subject / Learning Area</th>${labels.map(l=>`<th>${esc(l)}</th>`).join('')}<th>Final</th><th>Level / Grade</th><th>Teacher Comment</th></tr></thead><tbody>${buildRows(subjects, labels)}</tbody></table>
      <section class="summary"><div class="box"><b>Total Subjects</b>${subjects.length}</div><div class="box"><b>Fee Balance</b>${feeBalance === null || feeBalance === undefined ? '-' : `KES ${Number(feeBalance || 0).toLocaleString()}`}</div>${showClassPosition ? `<div class="box"><b>Class Position</b>${esc(classPositionText)}</div>` : `<div class="box"><b>Closing Date</b>${esc(data.closingDate || school.closingDate || '-')}</div>`}${showStreamPosition ? `<div class="box"><b>Stream Position</b>${esc(streamPositionText)}</div>` : `<div class="box"><b>Opening Date</b>${esc(data.openingDate || school.openingDate || '-')}</div>`}</section>
      <section class="comments"><div class="box comment-box"><b>Class Teacher Comment</b>${safeComment(classTeacherComment, ' ')}</div><div class="box comment-box"><b>Headteacher / Principal Comment</b>${safeComment(headteacherComment, ' ')}</div></section>
      <section class="signatures">${signatureHtml('Class Teacher Signature', classTeacherSig)}${signatureHtml('Headteacher / Principal Signature', headteacherSig)}<div><div class="stamp">School Stamp</div><div class="sig-label">Stamp</div></div></section>
      <div class="footer">${esc(branding.reportFooter || 'Generated by Shule AI.')}</div>
    </main></body></html>`;
  };

  // Keep any cached/older report output from showing the removed parent/guardian signature label.
  document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('.sig,.sig-label,.signature').forEach(el => {
      if (/parent\s*\/\s*guardian|parent|guardian/i.test(el.textContent || '')) el.remove();
    });
  });
})();
